import { expect, test } from "bun:test";
import { buildPickList, OrderFormatError, type PickList, type StockLot } from "./pickList";

test("format errors name the line", () => {
  const error = new OrderFormatError(7, "quantity must be positive");
  expect(error).toBeInstanceOf(Error);
  expect(error.line).toBe(7);
  expect(error.message).toBe("Line 7: quantity must be positive");
});

function plan(text: string, stock: StockLot[]): PickList | undefined {
  try {
    return buildPickList(text, stock);
  } catch (e) {
    if (e instanceof OrderFormatError) throw e;
    return undefined;
  }
}

function lot(bin: string, sku: string, qty: number, expires: string | null = null): StockLot {
  return { bin, sku, qty, expires };
}

test("one order with one item covered by one lot yields one pick", () => {
  expect(plan("ORDER 1001\nOLIVE-500 x3", [lot("A-01-1", "OLIVE-500", 10)])).toEqual({
    picks: [{ bin: "A-01-1", sku: "OLIVE-500", qty: 3, orderId: "1001" }],
    shortages: [],
  });
});
EOF
