python3 - <<'PY'
p='src/pickList.ts'
s=open(p).read()
start=s.index('export function buildPickList')
s=s[:start]+'''interface Order {
  id: string;
  priority: boolean;
  items: { sku: string; qty: number }[];
}

export function buildPickList(ordersText: string, stock: StockLot[]): PickList {
  const orders = parseOrders(ordersText);
  const served = [...orders.filter((o) => o.priority), ...orders.filter((o) => !o.priority)];
  const picks = allocate(served, stock);
  picks.sort((a, b) => compare(a.bin, b.bin));
  return { picks, shortages: [] };
}

function parseOrders(text: string): Order[] {
  const orders: Order[] = [];
  for (const raw of text.split("\\n")) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;
    const order = /^ORDER (\\S+)( +!)?$/.exec(line);
    if (order) {
      orders.push({ id: order[1], priority: order[2] !== undefined, items: [] });
      continue;
    }
    const [, sku, qty] = /^(\\S+) +x(\\d+)$/.exec(line)!;
    orders[orders.length - 1].items.push({ sku, qty: Number(qty) });
  }
  return orders;
}

function allocate(orders: Order[], stock: StockLot[]): Pick[] {
  const picks: Pick[] = [];
  const left = new Map(stock.map((l) => [l, l.qty]));
  const fefo = [...stock].sort(
    (a, b) => compare(a.expires ?? "\\uffff", b.expires ?? "\\uffff") || compare(a.bin, b.bin),
  );
  for (const order of orders) {
    for (const { sku, qty } of order.items) {
      let wanted = qty;
      for (const lot of fefo) {
        if (wanted === 0) break;
        if (lot.sku !== sku) continue;
        const taken = Math.min(wanted, left.get(lot)!);
        if (taken === 0) continue;
        left.set(lot, left.get(lot)! - taken);
        picks.push({ bin: lot.bin, sku, qty: taken, orderId: order.id });
        wanted -= taken;
      }
    }
  }
  return picks;
}

function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}
'''
open(p,'w').write(s)
PY
